// Compile a markdown digest from the three metrics branches.
// Branches: $('Metrics: Facebook (stub)'), $('Metrics: Instagram (stub)'), $('Metrics: Site (stub)')
const fb = $('Metrics: Facebook (stub)').first().json;
const ig = $('Metrics: Instagram (stub)').first().json;
const site = $('Metrics: Site (stub)').first().json;
const week = $now.minus({days: 7}).toFormat('MMM d') + ' – ' + $now.toFormat('MMM d, yyyy');
const digest = [
  `# Weekly analytics digest — ${week}`,
  '',
  '## Facebook', JSON.stringify(fb, null, 2),
  '',
  '## Instagram', JSON.stringify(ig, null, 2),
  '',
  '## Site', JSON.stringify(site, null, 2),
  '',
  '_Starter scaffold — replace this template with the client's KPI summary once the metrics nodes are connected._'
].join('\n');
return [{ json: { digest } }];
